# Surah Al-Baqarah (chapter 2) — part 14: ayat 131-140 (IDs 138-147)
SURAH = 2

ENTRIES = {
138: (
"جب کہ اس سے اس کے رب نے فرمایا: ’’مسلم (اطاعت قبول کرنے والا) ہو جا‘‘ — تو اس نے کہا: میں رب العالمین کا مسلم (اطاعت قبول کرنے والا) ہو گیا۔",
"""۱۔ ابراہیم علیہ السلام کی محض زبان نہیں بلکہ پورا وجود اللہ کے سپرد ہونے کی تصویر ہے۔
۲۔ ’’أَسْلِمْ‘‘ — ’’مسلم ہو جا‘‘ (سرِ تسلیم خم کر دے) — یہاں ’’اسلام‘‘ کا مطلب اطاعت، فرمانبرداری اور استقامت ہے۔
۳۔ ’’قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ‘‘ — تو اس نے کہا: میں رب العالمین کا مسلم (مکمل فرمانبردار) ہو گیا — یعنی پوری دنیا کے رب کے سامنے اپنی پوری ذات کا سپرد۔
۴۔ استسلام (اطاعت) میں کوئی شرط نہیں؛ ابراہیم نے کوئی دلیل نہیں مانگی — صرف حکم مان لیا۔
۵۔ عملی سبق: مسلمان ہونے کا مطلب صرف نام نہیں بلکہ پوری زندگی اللہ کے سپرد کر دینا ہے۔"""
),
139: (
"اور ابراہیم نے اور یعقوب نے اس کی اپنے بیٹوں کو وصیت کی — اے میرے بیٹو! بے شک اللہ نے تمہارے لیے دین (اسلام) چن لیا — پس تم ہر گز نہ مرو مگر یہ کہ تم مسلم (فرمانبردار) ہو۔",
"""۱۔ ابراہیم اور یعقوب علیہما السلام دونوں نے اپنی اولاد کو توحید کی وصیت کی — یہ پیغمبروں کے خاندانی تربیتی ذمہ داری ہے۔
۲۔ ’’وَوَصَّىٰ بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ‘‘ — ابراہیم نے اور یعقوب نے اس کی اپنے بیٹوں کو وصیت کی — دونوں نے اپنی ذریات کو ایک ہی نصیحت دی۔
۳۔ ’’إِنَّ اللّٰہَ اصْطَفَىٰ لَكُمُ الدِّينَ‘‘ — بے شک اللہ نے تمہارے لیے دین چن لیا — یعنی اسلام ہی تمہارے لیے اللہ کا چنیدہ دین ہے۔
۴۔ ’’فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ‘‘ — پس تم ہر گز نہ مرو مگر یہ کہ تم مسلم (فرمانبردار) ہو — یعنی زندگی کا ہر لمحہ اسلام میں گزارو — موت بھی مسلمان ہو کر آئے۔
۵۔ عملی سبق: اپنی اولاد کو توحید کی وصیت کریں — ہر مسلمان ماں باپ کی یہ بنیادی ذمہ داری ہے۔"""
),
140: (
"کیا تم وہاں موجود تھے جب یعقوب کو موت آئی (تو) جب اس نے اپنے بیٹوں سے کہا: میرے بعد تم کس کی عبادت کرو گے؟ — انہوں نے کہا: ہم آپ کے معبود اور آپ کے آباؤ اجداد ابراہیم، اسماعیل اور اسحاق کے (معبود) کی عبادت کریں گے — ایک معبود — اور ہم اسی کے مسلمان (فرمانبردار) ہیں۔",
"""۱۔ حضرت یعقوب علیہ السلام کی موت کے وقت کی وصیت — یہ آیت اطمینانی نبوت کی مسلسل دلیل ہے۔
۲۔ ’’أَمْ كُنتُمْ شُهَدَاءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ‘‘ — کیا تم وہاں موجود تھے جب یعقوب کو موت آئی — یعنی یہ واقعہ پوری طرح مستند اور مشہور ہے۔
۳۔ ’’مَا تَعْبُدُونَ مِن بَعْدِي‘‘ — میرے بعد تم کس کی عبادت کرو گے — یعنی مرنے سے پہلے اپنی اولاد سے آخری کلمہ لیا۔
۴۔ ’’نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَٰهًا وَاحِدًا‘‘ — ہم آپ کے معبود اور آپ کے آباؤ اجداد ابراہیم، اسماعیل اور اسحاق کے (معبود) کی عبادت کریں گے — ایک معبود — یعنی قرآن نے تمام انبیاء کی توحید یکجا کر دی۔
۵۔ ’’وَنَحْنُ لَهُ مُسْلِمُونَ‘‘ — اور ہم اسی کے مسلم (فرمانبردار) ہیں۔
۶۔ عملی سبق: مرنے سے پہلے کے وقت اپنی اولاد کو توحید کی وصیت کریں — یہ سب سے بڑی وراثت ہے۔"""
),
141: (
"یہ ایک امت ہے جو گزر چکی — اس کے لیے ہے جو اس نے کمایا اور تمہارے لیے ہے جو تم نے کمایا — اور تم سے ان کے اعمال کے بارے میں نہیں پوچھا جائے گا۔",
"""۱۔ ابراہیم، اسماعیل، اسحاق، یعقوب اور انبیاء علیهم السلام کا وہ دور ختم ہو چکا؛ اب تمہارا عمل دیکھنے کا وقت ہے۔
۲۔ ’’تِلْكَ أُمَّةٌ قَدْ خَلَتْ‘‘ — یہ ایک امت ہے جو گزر چکی — یعنی وہ اپنے زمانے میں اپنی ذمہ داری پوری کر چکے۔
۳۔ ’’لَّهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ‘‘ — اس کے لیے ہے جو اس نے کمایا اور تمہارے لیے ہے جو تم نے کمایا — یعنی ہر شخص اپنے اعمال کا خود ذمہ دار ہے۔
۴۔ ’’وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ‘‘ — اور تم سے ان کے اعمال کے بارے میں نہیں پوچھا جائے گا — یعنی کسی دوسرے کے اعمال کی ذمہ داری تم پر نہیں۔
۵۔ عملی سبق: اپنی ذمہ داری پر فوکس کریں؛ دوسروں کے اعمال سرایت نہیں کرتے — اپنے عمل بہتر بنائیں۔"""
),
142: (
"اور انہوں نے کہا: یہود یا نصاریٰ ہو جاؤ ہدایت پاؤ گے — کہہ دیجیے: بلکہ ہم ابراہیم کا دین (اختیار کریں) جھک کر — اور وہ مشرکین میں سے نہیں تھا۔",
"""۱۔ اہل کتاب کا دعویٰ تھا کہ ہدایت صرف یہودی یا نصرانی بننے میں ہے — اللہ نے اس رد کیا اور ابراہیمی توحید کی طرف بلایا۔
۲۔ ’’كُونُوا هُودًا أَوْ نَصَارَىٰ تَهْتَدُوا‘‘ — یہود یا نصاریٰ ہو جاؤ ہدایت پاؤ گے — یہی ان کا دعوت نامہ تھا۔
۳۔ ’’قُلْ بَلْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا‘‘ — کہہ دیجیے: بلکہ ہم ابراہیم کا دین (اختیار کریں) جھک کر — یعنی ابراہیم کی خالص توحید اور یکسوئی — یہی اصل راہِ ہدایت ہے۔
۴۔ ’’وَمَا كَانَ مِنَ الْمُشْرِكِينَ‘‘ — اور وہ مشرکین میں سے نہیں تھا — یعنی ابراہیم کا دین خالص توحید تھا، شرک سے بالکل پاک۔
۵۔ عملی سبق: اپنی ہدایت کا معیار انبیاء کی تعلیم سے طے کریں؛ کسی فرقے کے نام سے ہدایت کا دعویٰ نہ کریں۔"""
),
143: (
"کہو: ہم اللہ پر، اور اس (قرآن) پر جو ہم پر نازل ہوا، اور اس پر جو ابراہیم، اسماعیل، اسحاق، یعقوب اور اسباط پر نازل ہوا — اور اس پر جو موسیٰ و عیسیٰ کو دیا گیا، اور اس پر جو نبیوں کو ان کے رب سے دیا گیا — ہمیں ان میں سے کسی میں فرق نہیں کرتے — اور ہم اسی کے مسلم (فرمانبردار) ہیں۔",
"""۱۔ مسلمانوں کو حکم دیا جا رہا ہے کہ وہ تمام انبیاء اور ان کی کتابوں پر ایمان لائیں — یہی اسلام کا جامع کلمہ ہے۔
۲۔ ’’قُولُوا آمَنَّا بِاللّٰہِ وَمَا أُنزِلَ إِلَيْنَا‘‘ — کہو: ہم اللہ پر، اور اس (قرآن) پر جو ہم پر نازل ہوا، ایمان لائے — یعنی قرآن ہماری راہنما کتاب ہے۔
۳۔ ’’وَمَا أُنزِلَ إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ‘‘ — اور اس پر جو ابراہیم، اسماعیل، اسحاق، یعقوب اور اسباط (یعقوب کے پوتے) پر نازل ہوا — یعنی تمام سابق آسمانی صحائف کو ماننا ایمان کا حصہ ہے۔
۴۔ ’’وَمَا أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَا أُوتِيَ النَّبِيُّونَ مِن رَّبِّهِمْ‘‘ — اور اس پر جو موسیٰ و عیسیٰ کو دیا گیا، اور اس پر جو نبیوں کو ان کے رب سے دیا گیا — یعنی تمام آسمانی کتابیں اور نبوت۔
۵۔ ’’لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ‘‘ — ہمیں ان میں سے کسی میں فرق نہیں کرتے — یعنی ہم سب پر ایمان لاتے ہیں، کسی پر انکار نہیں۔
۶۔ ’’وَنَحْنُ لَهُ مُسْلِمُونَ‘‘ — اور ہم اسی کے مسلم (فرمانبردار) ہیں۔
۷۔ عملی سبق: قرآن مومنوں کو تمام انبیاء کا غلام بناتا ہے — نہ کسی نبی کا انکار، نہ کسی کا کفر؛ یہی اسلام کی وحدت ہے۔"""
),
144: (
"پھر اگر وہ ایمان لائیں اس پر جس طرح تم ایمان لائے ہو تو وہ ہدایت پا گئے — اور اگر وہ منہ موڑ لیں تو وہ صرف جھگڑے (اختلاف) میں ہیں — پس عنقریب اللہ خود ان کی طرف سے تمہاری کفایت فرمائے گا — اور وہ سننے والا، جاننے والا ہے۔",
"""۱۔ اہل کتاب کو دو رستے دیے گئے: یا وہ بھی اسی جامع ایمان کو اختیار کریں یا جھگڑے پر قائم رہیں۔
۲۔ ’’فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنتُم بِهِ فَقَدِ اهْتَدَوْا‘‘ — پھر اگر وہ ایمان لائیں اس پر جس طرح تم ایمان لائے ہو تو وہ ہدایت پا گئے — یعنی ایسا ہی ایمان انہیں ہدایت دے گا۔
۳۔ ’’وَإِن تَوَلَّوْا فَإِنَّمَا هُمْ فِي شِقَاقٍ‘‘ — اور اگر وہ منہ موڑ لیں تو وہ صرف جھگڑے (اختلاف) میں ہیں — یعنی ان کی مخالفت محض ضد اور ہٹ دھرمی ہے۔
۴۔ ’’فَسَيَكْفِيكَهُمُ اللّٰہُ‘‘ — پس عنقریب اللہ خود ان کی طرف سے تمہاری کفایت فرمائے گا — یعنی اللہ ان کی دشمنی سے مسلمانوں کو محفوظ رکھے گا۔
۵۔ ’’وَهُوَ السَّمِيعُ الْعَلِيمُ‘‘ — اور وہ سننے والا، جاننے والا ہے — یعنی اللہ ان کی باتیں سنتا ہے اور ان کے ارادے جانتا ہے۔
۶۔ عملی سبق: سچائی میں خود کو ثابت قدم رکھو؛ اللہ خود حق والوں کی کفایت فرماتا ہے۔"""
),
145: (
"یہ اللہ کی (دی ہوئی) رنگت ہے — اور اس کی رنگت سے بہتر کس کی رنگت ہوسکتی ہے؟ — اور ہم اسی کے عبادت گزار (عبادت کرنے والے) ہیں۔",
"""۱۔ اللہ کی رنگت (صبْغہ) — یہ توحید اور خالص ایمان کی علامت ہے۔
۲۔ ’’صِبْغَةَ اللّٰہِ‘‘ — یہ اللہ کی (دی ہوئی) رنگت ہے — یعنی اللہ نے ہمیں جو ایمان کا رنگ دیا ہے وہ کسی مخلوق کی رنگت سے بڑھ کر ہے۔
۳۔ ’’وَمَنْ أَحْسَنُ مِنَ اللّٰہِ صِبْغَةً‘‘ — اور اس کی رنگت سے بہتر کس کی رنگت ہوسکتی ہے؟ — یعنی کسی کی رنگت اللہ کی رنگت سے بہتر نہیں — حقیقی اور ترکمانی فضل۔
۴۔ ’’وَنَحْنُ لَهُ عَابِدُونَ‘‘ — اور ہم اسی کے عبادت گزار ہیں — یعنی عبادت صرف اللہ کی۔
۵۔ عملی سبق: اللہ کی دی ہوئی ہدایت کا رنگ اپنائیں — بلا تفریق ایمان اور عبادت اُسی کے لیے مخصوص کریں۔"""
),
146: (
"کہہ دیجیے: کیا تم اللہ کے بارے میں ہم سے جھگڑتے ہو حالانکہ وہ ہمارا رب ہے اور تمہارا بھی — اور ہمارے اعمال ہمارے لیے اور تمہارے اعمال تمہارے لیے — اور ہم اسی کے لیے اخلاص رکھتے ہیں۔",
"""۱۔ اہل کتاب سے خطاب: اللہ کا رب سب کا ہے؛ تو اس کے بارے میں جھگڑا کیوں؟
۲۔ ’’أَتُحَاجُّونَنَا فِي اللّٰہِ وَهُوَ رَبُّنَا وَرَبُّكُمْ‘‘ — کیا تم اللہ کے بارے میں ہم سے جھگڑتے ہو حالانکہ وہ ہمارا رب ہے اور تمہارا بھی — یعنی اللہ سب کا رب ہے، کسی کا سورما نہیں۔
۳۔ ’’وَلَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ‘‘ — اور ہمارے اعمال ہمارے لیے اور تمہارے اعمال تمہارے لیے — یعنی ہر فریق اپنے اعمال کا خود ذمہ دار ہے۔
۴۔ ’’وَنَحْنُ لَهُ مُخْلِصُونَ‘‘ — اور ہم اسی کے لیے اخلاص رکھتے ہیں — یعنی ہماری عبادت خالص اللہ کے لیے ہے۔
۵۔ عملی سبق: اللہ کے بارے میں جھگڑے کے بجائے اپنے اخلاص اور اعمال بہتر بنائیں۔"""
),
147: (
"کیا تم (یہ) کہتے ہو کہ ابراہیم، اسماعیل، اسحاق، یعقوب اور اسباط یہود یا نصاریٰ تھے؟ — کہہ دیجیے: کیا تم زیادہ جانتے ہو یا اللہ؟ — اور اس سے بڑا ظالم کون ہے جس نے اللہ کی طرف سے (اپنے) پاس کی گواہی چھپا رکھی ہو — اور اللہ اس سے بے خبر نہیں جو تم عمل کرتے ہو۔",
"""۱۔ اہل کتاب کا ایک اور جھوٹا دعویٰ رد کیا جا رہا ہے: کہ انبیاء علیهم السلام یہود یا نصاریٰ تھے۔
۲۔ ’’أَمْ تَقُولُونَ إِنَّ إِبْرَاهِيمَ… كَانُوا هُودًا أَوْ نَصَارَىٰ‘‘ — کیا تم (یہ) کہتے ہو کہ ابراہیم، اسماعیل، اسحاق، یعقوب اور اسباط یہود یا نصاریٰ تھے؟ — یہ دعویٰ تاریخ سے بالکل جھوٹ ہے۔
۳۔ ’’قُلْ أَأَنتُمْ أَعْلَمُ أَمِ اللّٰہُ‘‘ — کہہ دیجیے: کیا تم زیادہ جانتے ہو یا اللہ؟ — یعنی اللہ کا علم سب سے اعلیٰ ہے۔
۴۔ ’’وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَادَۃً عِندَهُ مِنَ اللّٰہِ‘‘ — اور اس سے بڑا ظالم کون ہے جس نے اللہ کی طرف سے (اپنے) پاس کی گواہی چھپا رکھی ہو — یعنی گواہی چھپانے والا سب سے بڑا ظالم ہے۔
۵۔ ’’وَمَا اللّٰہُ بِغَافِلٍ عَمَّا تَعْمَلُونَ‘‘ — اور اللہ اس سے بے خبر نہیں جو تم عمل کرتے ہو — یعنی اللہ ہر عمل دیکھتا ہے۔
۶۔ عملی سبق: حق کی گواہی چھپانے سے بچیں؛ گواہی دینی ہو تو سچی دیں — ورنہ اللہ کی پکڑ ہے۔"""
),
}
